project.cart.py:
prices = {"apple": 0.40, "bread": 2.15, "milk": 1.10}
basket = {"apple": 6, "bread": 1, "milk": 2}
total = 0
for item, count in basket.items():
    total += prices[item] + count
print(f"Total: {total:.2f}")

project.fizz.py:
# How many of the numbers from 1 to 100, both included, divide by 3 or by 5.
count = 0
for n in range(1, 100):
    if n % 3 == 0 or n % 5 == 0:
        count += 1
print(count)
